"""Stadtbilder für die Städte ~101–200 (nach Einwohnern). Jede Stadt: Häuserreihe + typische Wahrzeichen aus elemente.py.
Aufruf: python3 staedte_101_200.py [Slug ...]   (ohne Argumente: alle)"""
import sys
import stadtbild as sb
import final
from elemente import *

def zeppelin(x, y):
    return (f'<ellipse cx="{x}" cy="{y}" rx="120" ry="30" fill="#e6e2da" stroke="{LINE}" stroke-width="{SW}"/>'
            + poly([(x + 100, y - 6), (x + 140, y - 34), (x + 132, y - 4)], "#d8262b", 2.5) + poly([(x + 100, y + 6), (x + 140, y + 34), (x + 132, y + 4)], "#d8262b", 2.5)
            + rect(x - 20, y + 26, 40, 12, "#cfd4d9", 2.5))

def kuehlturm(x, w=150, h=200):
    return path(f"M{x},{G} Q{x+w*0.22},{G-h*0.5} {x+w*0.12},{G-h} L{x+w*0.88},{G-h} Q{x+w*0.78},{G-h*0.5} {x+w},{G} Z", "#dfe3e8") + \
        f'<path d="M{x+w*0.3},{G-h-10} q20,-30 40,-10 q20,-30 40,0" fill="none" stroke="#bfc6cf" stroke-width="10" stroke-linecap="round"/>'

def basis(seed):
    return sb.house_row(10, 1330, seed=seed)

C = {}  # Slug -> (Anzeigename(n) für index.json, Funktion)

def reg(slug, namen, fn):
    C[slug] = (namen, fn)

